import{_ as t,o as l,c as a,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/unterricht-kataloge/kataloge-jahrgaenge.png",f=JSON.parse('{"title":"Jahrgänge und ihre Statistikzuordnung festlegen","description":"","frontmatter":{"title":"Jahrgänge und ihre Statistikzuordnung festlegen","source_pageid":1649,"source_revision":7089},"headers":[],"relativePath":"schild3/unterricht-kataloge/jahrgaenge-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/jahrgaenge-schulbezogene-kataloge.md"}'),g={name:"schild3/unterricht-kataloge/jahrgaenge-schulbezogene-kataloge.md"};function d(u,i,o,h,c,k){return l(),a("div",null,[...i[0]||(i[0]=[r('<h1 id="jahrgange-und-ihre-statistikzuordnung-festlegen" tabindex="-1">Jahrgänge und ihre Statistikzuordnung festlegen <a class="header-anchor" href="#jahrgange-und-ihre-statistikzuordnung-festlegen" aria-label="Permalink to &quot;Jahrgänge und ihre Statistikzuordnung festlegen&quot;">​</a></h1><p>Legen Sie schulinterne Jahrgangsbezeichnungen, Statistikzuordnung und Gliederung fest. Der Artikel erläutert auch die getrennte Erfassung der Schuleingangsphase.</p><p><a href="/bilder/unterricht-kataloge/kataloge-jahrgaenge.png"><img src="'+s+'" alt="Katalog der Jahrgänge." loading="lazy"></a></p><p><em>Katalog der Jahrgänge.</em></p><p>Bei den Jahrgängen handelt es sich um eine entscheidende Tabelle in SchILD-NRW. Hier wird festgelegt, welche Jahrgänge in den Bildungsgängen zur Verfügung stehen und wie diese an die Statistik übermittelt werden.</p><p>Dabei gibt es folgende Einstellungsmöglichkeiten:</p><ul><li><strong>Statistik-Kürzel</strong> und <strong>Statistik-Bez.</strong>: Hier wählen Sie den Jahrgang aus, der an die Statistik (ASDPC32) übermittelt werden soll. Sie können hier nur aus Optionen, die für Ihre Schulform vorgegeben sind!</li></ul>',7),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("An Grundschulen werden die "),e("strong",null,"Jahrgänge 01, 02, 03 und 04"),n(" verwendet. "),e("strong",null,"E1, E2 und E3"),n(" sind keine eigenen Jahrgänge, sondern zusätzliche EP-Jahre für den Verbleib in den Jahrgängen "),e("strong",null,"01 und 02"),n(". Die Zuordnung erfolgt in jedem Halbjahr unter "),e("strong",null,"Schüler ➜ Akt. Halbjahr ➜ Allgemeine Angaben ➜ EP-Jahr"),n(". In Individualdaten I wird der Wert zunächst nur angezeigt; ab Jahrgang 03 kann er dort korrigiert werden. Siehe "),e("a",{href:"/schild3/schueler/eintragung-der-ep-jahre-tutorial.html"},"Die Jahre der Schuleingangsphase eintragen"),n(".")])],-1),e("ul",null,[e("li",null,[e("strong",null,"Schulinternes Kürzel"),n(": An dieser Stelle können Sie dem Jahrgang eine eigene individuelle Bezeichnung geben. Diese Bezeichnung wird an den meisten Stellen in SchILD-NRW angezeigt und steht i.d.R. als ASD-Jahrgang zur Verfügung.")]),e("li",null,[e("strong",null,"Gliederung (Klartext)"),n(": Hier tragen Sie die Gliederung für den Bildungsgang ein. An den meisten Schulen steht hier nur "),e("em",null,'"Standard für diese Schulform"'),n(' zur Verfügung. Es werden alle Gliederungen angezeigt, die unter "Verwaltung" ➜ "Schule" ➜ "Allgemeine Angaben" eingetragen sind.')])],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Die benötigten Schulgliederungen hängen von der Schulform ab. Beispiele sind katholische oder evangelische Bekenntnisgrundschulen und Gemeinschaftsgrundschulen. An Sekundarschulen können auslaufende Haupt- oder Realschulgliederungen vorkommen, an Gesamtschulen zusätzliche gymnasiale Bildungsgänge."),e("p",null,"Am Berufskolleg müssen alle vorhandenen Bildungsgänge erfasst sein. Für jeden Jahrgang einer Gliederung muss ein Statistikjahrgang zur Verfügung stehen. Klären Sie unklare Zuordnungen mit Ihrer Bezirksregierung oder IT.NRW.")],-1),e("ul",null,[e("li",null,[e("strong",null,"Gliederung (Kürzel)"),n(": Hier steht ein dreistelliges Statistikkürzel. (*** bei Standard-Gliederung)")]),e("li",null,[e("strong",null,"Kurzbez."),n(": Hier können Sie eine Kurzbezeichnung vergeben, die zum Beispiel im Listendruck mit dem Reportbaukasten verwendet werden kann.")]),e("li",null,[e("strong",null,"Sek.-Stufe"),n(": Hier werden die Jahrgänge der Primarstufe (Pr), der Sekundarstufe I oder der Sekundarstufe II zugeordnet.")])],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,'Bei der Sek-II sind in der gymnasialen Oberstufe und bei den BKs "SII-1" bis "SII-3" einzutragen, so dass SchILD bei Bedarf die Karteireiter "Abitur" und "FHR" einblenden kann. Alle weiteren Jahrgänge am BK werden mit SII-BK gekennzeichnet.')],-1),e("ul",null,[e("li",null,[e("strong",null,"Restabschn."),n(" gibt die Zahl der Lernabschnitte bis zum Abschluss der Schulform an. Bei halbjährlicher Organisation sind es im Grundschuljahrgang 04 und in der Q2 jeweils zwei Abschnitte. Bei Quartalsorganisation umfasst ein Schuljahr vier Abschnitte. Verwenden Sie daher die zur Organisation Ihrer Schule passende Anzahl. EP-Jahre werden hier nicht als eigene Jahrgänge angelegt.")])],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Diese Spalte sollte ausgefüllt werden, denn mit diesen Angaben wird das Datum des voraussichtlichen Abschlusses berechnet. Im Nachhinein kann die Berechnung über einen Gruppenprozess angestoßen werden.")],-1),e("ul",null,[e("li",null,[e("strong",null,"Folgejahrgang"),n(" bestimmt, in welchen Jahrgang bei der Versetzung ins neue Schuljahr gewechselt wird. Nutzen Sie das Feld auch für besondere Jahrgangsfolgen oder einen damit verbundenen Gliederungswechsel am Berufskolleg. Bei Abschlussjahrgängen bleibt es leer.")])],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Wenn ein Folgejahrgang eingetragen ist, dann muss dies für alle bestehenden Jahrgänge gemacht werden. Sind alle Folgejahrgänge leer, richtet sich SchILD-NRW nach der Klassen-/Versetzungstabelle. Diese Spalte ist also optional.")],-1),r('<ul><li><p><strong>Chronol.</strong> kennzeichnet Jahrgänge, die innerhalb einer Gliederung aufeinanderfolgen. Ordnen Sie diese mit den roten Pfeilen in zeitlicher Reihenfolge. Diese Reihenfolge wird bei der Versetzung benötigt, wenn in der Klassen-/Versetzungstabelle kein Folgejahrgang festgelegt ist. Sie erleichtert zugleich den Überblick.</p></li><li><p><strong>Sichtbar</strong> bestimmt, ob ein Jahrgang zur Auswahl steht. Wird ein Jahrgang nicht mehr benötigt, können Sie ihn ausblenden. Prüfen Sie vorher auch die vergangenen Lernabschnitte aktiver Schülerinnen und Schüler: Solange der Jahrgang dort noch benötigt wird, muss er sichtbar bleiben.</p></li><li><p><strong>Sortierung</strong>: Hier kann, wie in allen Katalogen, die Reihenfolge der Anzeige bestimmt werden. Bitte beachten Sie in diesem Sonderfall den Zusammenhang mit der Spalte &quot;chronologisch&quot;.</p></li></ul><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Jahrg%C3%A4nge_(Schulbezogene_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7089.</p>',3)])])}const m=t(g,[["render",d]]);export{f as __pageData,m as default};
